def write_status(authenticated, role):
    if not authenticated:
        return 401
    if role != 'admin':
        return 403
    return 201
for signed_in, role in [(False, 'admin'), (True, 'reader'), (True, 'admin')]:
    print(write_status(signed_in, role))

import hashlib
import secrets
from fastapi import Depends, FastAPI, HTTPException
from fastapi.security import HTTPBearer
from fastapi.testclient import TestClient
app = FastAPI()
bearer = HTTPBearer(auto_error=False)
reader_token = secrets.token_urlsafe(32)
admin_token = secrets.token_urlsafe(32)
# مخزن اختبار موثوق في ذاكرة الخادم؛ المشروع الفعلي يقرأ القاعدة.
sessions = {hashlib.sha256(reader_token.encode()).hexdigest(): 'reader',
            hashlib.sha256(admin_token.encode()).hexdigest(): 'admin'}
def current_role(credentials=Depends(bearer)):
    if credentials is None:
        raise HTTPException(status_code=401, detail='يلزم الدخول')
    digest = hashlib.sha256(credentials.credentials.encode()).hexdigest()
    role = sessions.get(digest)
    if role is None:
        raise HTTPException(status_code=401, detail='جلسة غير صالحة')
    return role
def require_admin(role=Depends(current_role)):
    if role != 'admin':
        raise HTTPException(status_code=403, detail='صلاحية غير كافية')
@app.post('/products', status_code=201, dependencies=[Depends(require_admin)])
def create_product():
    return {'id': 1}
with TestClient(app) as client:
    print(client.post('/products').status_code)
    for token in (reader_token, admin_token):
        print(client.post('/products', headers={'Authorization': 'Bearer ' + token}).status_code)

